var events = $input.all().map(function(item) { return item.json; });
var now = new Date();
var todayStr = now.toISOString().split('T')[0];

var WORK_START = 8;
var WORK_END = 18;
var WORK_HOURS = WORK_END - WORK_START;

function getDateStr(dt) { return new Date(dt).toISOString().split('T')[0]; }
function getHour(dt) { return new Date(dt).getHours() + new Date(dt).getMinutes() / 60; }

var realEvents = events.filter(function(e) {
  if (!e.start || !e.start.dateTime) return false;
  if (e.status === 'cancelled' || e.status === 'declined') return false;
  var attendees = e.attendees || [];
  var others = attendees.filter(function(a) { return a.email !== 'nelson.torres@adquadrant.com'; });
  if (attendees.length > 0 && others.length === 0) return false;
  return true;
});

var dayMap = {};
realEvents.forEach(function(e) {
  var day = getDateStr(e.start.dateTime);
  if (!dayMap[day]) dayMap[day] = [];
  dayMap[day].push({
    summary: e.summary,
    start: new Date(e.start.dateTime),
    end: new Date(e.end.dateTime),
    startHour: getHour(e.start.dateTime),
    endHour: getHour(e.end.dateTime),
    attendees: (e.attendees || []).map(function(a) { return a.email; })
  });
});

var alerts = [];
var dailySummaries = [];

Object.keys(dayMap).sort().forEach(function(day) {
  var meetings = dayMap[day].sort(function(a, b) { return a.start - b.start; });
  var totalMeetingHours = 0;
  meetings.forEach(function(m) {
    var s = Math.max(m.startHour, WORK_START);
    var e = Math.min(m.endHour, WORK_END);
    if (e > s) totalMeetingHours += (e - s);
  });
  var meetingPct = Math.round((totalMeetingHours / WORK_HOURS) * 100);

  var freeBlocks = [];
  var lastEnd = WORK_START;
  meetings.forEach(function(m) {
    var s = Math.max(m.startHour, WORK_START);
    if (s > lastEnd) freeBlocks.push({ start: lastEnd, end: s, duration: s - lastEnd });
    lastEnd = Math.max(lastEnd, Math.min(m.endHour, WORK_END));
  });
  if (lastEnd < WORK_END) freeBlocks.push({ start: lastEnd, end: WORK_END, duration: WORK_END - lastEnd });
  var longestBlock = freeBlocks.reduce(function(max, b) { return b.duration > max ? b.duration : max; }, 0);
  var longestBlockMin = Math.round(longestBlock * 60);

  var consecutive = 0;
  var maxConsecutive = 0;
  for (var i = 0; i < meetings.length; i++) {
    if (i > 0 && (meetings[i].startHour - meetings[i-1].endHour) < 0.25) {
      consecutive++;
    } else {
      consecutive = 1;
    }
    if (consecutive > maxConsecutive) maxConsecutive = consecutive;
  }

  var contextSwitches = 0;
  for (var j = 1; j < meetings.length; j++) {
    var gap = meetings[j].startHour - meetings[j-1].endHour;
    if (gap < 0.25 && gap >= 0) {
      var prevAttendees = meetings[j-1].attendees.join(',');
      var currAttendees = meetings[j].attendees.join(',');
      if (prevAttendees !== currAttendees) contextSwitches++;
    }
  }

  var isToday = day === todayStr;
  var dayLabel = isToday ? 'Today (' + day + ')' : day;
  var dayData = {
    day: dayLabel,
    meetingCount: meetings.length,
    meetingPct: meetingPct,
    totalMeetingHours: Math.round(totalMeetingHours * 10) / 10,
    longestFreeBlockMin: longestBlockMin,
    maxConsecutive: maxConsecutive,
    contextSwitches: contextSwitches
  };
  dailySummaries.push(dayData);

  if (isToday) {
    if (meetingPct > 60) alerts.push('Meeting load is ' + meetingPct + '% of working hours today.');
    if (longestBlockMin < 90) alerts.push('Longest uninterrupted block today is only ' + longestBlockMin + ' minutes.');
    if (maxConsecutive >= 3) alerts.push(maxConsecutive + ' back-to-back meetings detected today.');
    if (contextSwitches >= 2) alerts.push(contextSwitches + ' context switches (different attendee groups < 15 min apart).');
  }
});

var isOverloaded = alerts.length > 0;
var lines = [];
if (isOverloaded) {
  lines.push('*Calendar Health Warning*');
  lines.push('');
  alerts.forEach(function(a) { lines.push('- ' + a); });
  lines.push('');
}
lines.push('*Weekly Calendar Overview:*');
dailySummaries.forEach(function(d) {
  var emoji = d.meetingPct > 60 ? '\uD83D\uDD34' : d.meetingPct > 40 ? '\uD83D\uDFE1' : '\uD83D\uDFE2';
  lines.push(emoji + ' ' + d.day + ': ' + d.meetingCount + ' meetings (' + d.meetingPct + '%), longest free block: ' + d.longestFreeBlockMin + 'min');
});

var lowDensityDays = dailySummaries.filter(function(d) { return d.meetingPct < 30 && !d.day.startsWith('Today'); });
if (lowDensityDays.length > 0) {
  lines.push('');
  lines.push('*Suggested focus time days:* ' + lowDensityDays.map(function(d) { return d.day; }).join(', '));
}

lines.push('');
lines.push('_\u2726 Iris \u2014 Nelson\'s personal AI assistant_');

return [{ json: {
  is_overloaded: isOverloaded,
  message: lines.join('\n'),
  alert_count: alerts.length,
  daily_summaries: dailySummaries
}}];

